with open(CSV_PATH, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
    base_cols = list(reader.fieldnames)

assert "sample_friendlyId" in base_cols, base_cols

matched = 0
for row in rows:
    fid = (row.get("sample_friendlyId") or "").strip()
    if fid in RES:
        vals = RES[fid]
        for col, v in zip(NEW_COLS, vals):
            row[col] = v
        matched += 1

for row in rows:
    for c in NEW_COLS:
        row.setdefault(c, "")

new_fieldnames = base_cols + [c for c in NEW_COLS if c not in base_cols]
with open(CSV_PATH, 'w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=new_fieldnames, lineterminator='\n')
    writer.writeheader()
    writer.writerows(rows)

print(f"Filled {matched} rows (unique friendlyIds)")
# sanity: check no unexpected filled rows remain outside RES keys
extra = [r["street"] for r in rows if r.get("parking_hall_exists") and (r.get("sample_friendlyId") or "").strip() not in RES]
print("Unexpectedly-filled rows (should be []):", extra)
